VOWELS = "aeiou"


def _translate_word(word):
    # Rule 1: starts with a vowel, or with "xr" or "yt".
    if word[0] in VOWELS or word[:2] in ("xr", "yt"):
        return word + "ay"

    # Move the leading consonant cluster to the end (Rules 2-4).
    i = 0
    while i < len(word):
        if word[i] in VOWELS:
            break  # Rule 2: stop at the first vowel.
        if word[i] == "y" and i > 0:
            break  # Rule 4: "y" acts as a vowel after consonants.
        if word[i : i + 2] == "qu":
            i += 2  # Rule 3: include the "qu" in the moved cluster.
            break
        i += 1

    return word[i:] + word[:i] + "ay"


def translate(text):
    return " ".join(_translate_word(word) for word in text.split(" "))

